#!/usr/bin/env node
// Generates the frontend API contract from the backend OpenAPI document.
//
//   npm run api:generate   rewrite src/generated/api-openapi.json and src/generated/api.ts
//   npm run api:check      exit 1 when either generated file is stale
//
// Only the operations the frontend calls are taken (an explicit allowlist), with the component
// schemas they reference. Adding an operation here is a deliberate step after the backend contract
// for it is committed.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import openapiTS, { astToString } from 'openapi-typescript';

const here = path.dirname(fileURLToPath(import.meta.url));
const frontendRoot = path.resolve(here, '..');
const sourceFile = path.resolve(frontendRoot, '../express-backend/openapi/openapi.json');
const outputDir = path.join(frontendRoot, 'src/generated');
const contractFile = path.join(outputDir, 'api-openapi.json');
const typesFile = path.join(outputDir, 'api.ts');

const OPERATION_IDS = [
  // Authentication (backend Task 06)
  'login',
  'getCurrentUser',
  'logout',
  // Employee directory (backend Task 07)
  'listEmployees',
  'getEmployee',
  'getDirectoryOptions',
  // Read-only compensation assistant (backend Task 08)
  'sendAssistantMessages',
  // Salary adjustments and approval requests (backend Task 09)
  'previewSalaryAdjustment',
  'applySalaryAdjustment',
  'submitSalaryAdjustmentRequest',
  'listSalaryAdjustmentRequests',
  'getSalaryAdjustmentRequest',
  'approveSalaryAdjustmentRequest',
  'cancelSalaryAdjustmentRequest',
  // Compensation dashboard, read-only (backend Task 10)
  'getDashboardSummary',
  'getDashboardBreakdown',
  'getDashboardRecentChanges',
  'getDashboardWithoutRecentAdjustment',
];

function collectRefs(value, found) {
  if (Array.isArray(value)) {
    for (const item of value) collectRefs(item, found);
  } else if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      if (key === '$ref' && typeof child === 'string') found.add(child);
      else collectRefs(child, found);
    }
  }
}

function selectContract(document) {
  const paths = {};
  const seen = new Set();
  for (const [route, operations] of Object.entries(document.paths ?? {})) {
    for (const [method, operation] of Object.entries(operations)) {
      if (!OPERATION_IDS.includes(operation?.operationId)) continue;
      paths[route] ??= {};
      paths[route][method] = operation;
      seen.add(operation.operationId);
    }
  }
  const missing = OPERATION_IDS.filter((id) => !seen.has(id));
  if (missing.length > 0) {
    throw new Error(`backend OpenAPI is missing operations: ${missing.join(', ')}`);
  }

  // Copy only the component schemas the selected operations reach, following nested references.
  const schemas = {};
  const pending = new Set();
  collectRefs(paths, pending);
  while (pending.size > 0) {
    const [ref] = pending;
    pending.delete(ref);
    const prefix = '#/components/schemas/';
    if (!ref.startsWith(prefix)) throw new Error(`unsupported reference: ${ref}`);
    const name = ref.slice(prefix.length);
    if (schemas[name]) continue;
    const schema = document.components?.schemas?.[name];
    if (!schema) throw new Error(`unresolved reference: ${ref}`);
    schemas[name] = schema;
    const nested = new Set();
    collectRefs(schema, nested);
    for (const child of nested) if (!schemas[child.slice(prefix.length)]) pending.add(child);
  }

  const sortedSchemas = Object.fromEntries(Object.keys(schemas).sort().map((name) => [name, schemas[name]]));
  return {
    openapi: document.openapi,
    info: { ...document.info, title: `${document.info.title} (frontend subset)` },
    paths,
    components: { schemas: sortedSchemas, securitySchemes: document.components?.securitySchemes ?? {} },
  };
}

async function render() {
  const document = JSON.parse(await readFile(sourceFile, 'utf8'));
  const contract = selectContract(document);
  const contractText = `${JSON.stringify(contract, null, 2)}\n`;
  const ast = await openapiTS(contract);
  const header =
    '// Generated by scripts/generate-api-contract.mjs from express-backend/openapi/openapi.json.\n' +
    '// Do not edit. Run `npm run api:generate`.\n\n';
  const typesText = `${header}${astToString(ast)}`;
  return { contractText, typesText };
}

async function readOrEmpty(file) {
  try {
    return await readFile(file, 'utf8');
  } catch {
    return '';
  }
}

const check = process.argv.includes('--check');
const { contractText, typesText } = await render();
if (check) {
  const stale = [];
  if ((await readOrEmpty(contractFile)) !== contractText) stale.push(path.relative(frontendRoot, contractFile));
  if ((await readOrEmpty(typesFile)) !== typesText) stale.push(path.relative(frontendRoot, typesFile));
  if (stale.length > 0) {
    console.error(`Generated API contract is stale: ${stale.join(', ')}. Run \`npm run api:generate\`.`);
    process.exit(1);
  }
  console.log('Generated API contract is current.');
} else {
  await mkdir(outputDir, { recursive: true });
  await writeFile(contractFile, contractText);
  await writeFile(typesFile, typesText);
  console.log(`Wrote ${path.relative(frontendRoot, contractFile)} and ${path.relative(frontendRoot, typesFile)}.`);
}
